477:fn threetched_connection_failure(
478:    error: &tokio_tungstenite::tungstenite::Error,
479:) -> ThreetchedConnectionFailure {
480:    use tokio_tungstenite::tungstenite::Error;
481:    let mut failure = ThreetchedConnectionFailure {
482:        kind: "other",
483:        http_status: None,
484:        gateway_reason: "unspecified",
485:    };
486:    failure.kind = match error {
487:        Error::Http(response) => {
488:            failure.http_status = Some(response.status().as_u16());
489:            failure.gateway_reason = match response.body().as_deref() {
490:                Some(b"stateless_generation_not_admitted") => "not_admitted",
491:                Some(b"stateless_generation_invalid_session") => "invalid_session",
492:                Some(b"stateless_generation_identity_rejected") => "identity_rejected",
493:                Some(b"stateless_generation_identity_required") => "identity_required",
494:                Some(b"stateless_generation_unavailable") => "generation_unavailable",
495:                _ => "unspecified",
496:            };
497:            "http"
498:        }
499:        Error::Io(_) => "io",
500:        Error::Tls(_) => "tls",
501:        Error::Protocol(_) => "protocol",
502:        Error::Capacity(_) => "capacity",
503:        Error::ConnectionClosed | Error::AlreadyClosed => "closed",
504:        _ => "other",
505:    };
